CREATE DATABASE IF NOT EXISTS pc_builder CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE pc_builder;
DROP TABLE IF EXISTS subscriptions, builds, components, users;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE components (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, type ENUM('cpu','motherboard','ram','gpu','ssd','psu','case') NOT NULL, name VARCHAR(180) NOT NULL, brand VARCHAR(80) NOT NULL, price DECIMAL(10,2) NOT NULL, socket VARCHAR(30) NULL, memory_type ENUM('DDR4','DDR5') NULL, wattage INT NULL, tdp INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE builds (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, components_json JSON NOT NULL, total_price DECIMAL(10,2) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE subscriptions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, plan ENUM('free','standard','pro') NOT NULL DEFAULT 'free', status ENUM('active','cancelled') NOT NULL DEFAULT 'active', started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
